-- Prosody Bench: Postgres port of the SQLite schema that lived in lib/db.ts.
--
-- Access model: every table has RLS enabled and NO policies, and anon/authenticated have no
-- grants. Only the service role (used by our server code through SUPABASE_SERVICE_ROLE_KEY,
-- which bypasses RLS) can read or write. The browser never talks to Supabase directly.
--
-- Ported SQLite-isms:
--   AUTOINCREMENT                → bigint generated by default as identity (by default, so the
--                                  one-off migration script can keep existing ids)
--   datetime('now') / strftime   → timestamptz default now()
--   is_attention_check 0/1       → boolean
--   SUM(a = b)                   → count(*) filter (where a = b)
--   INSERT … WHERE NOT EXISTS    → UNIQUE constraint + ON CONFLICT DO NOTHING (in the client)
--   lastInsertRowid              → RETURNING id (in the client)
--   PRAGMA foreign_keys          → always on in Postgres

-- ---------------------------------------------------------------- survey trials

create table public.exp1_trials (
  id bigint generated by default as identity primary key,
  participant text not null,
  trial_number integer,
  is_attention_check boolean not null,
  provider text,
  condition text not null,
  take integer,
  audio_file text,
  intended_question text,
  naturalness integer check (naturalness between 1 and 5),
  human_or_ai text check (human_or_ai in ('Human', 'AI')),
  question_answered text,
  check (is_attention_check or (provider is not null and intended_question is not null))
);

create table public.exp2_trials (
  id bigint generated by default as identity primary key,
  participant text not null,
  trial_number integer,
  is_attention_check boolean not null,
  provider text,
  condition text not null,
  variant text check (variant in ('a', 'b')),
  take integer,
  audio_file text,
  intended_interpretation text check (intended_interpretation in ('A', 'B')),
  interpretation text check (interpretation in ('A', 'B')),
  naturalness integer check (naturalness between 1 and 5),
  check (is_attention_check or (provider is not null and intended_interpretation is not null))
);

-- ---------------------------------------------------------------- arena responses

create table public.responses (
  id bigint generated by default as identity primary key,
  participant text not null,
  session text not null,
  round integer not null,
  experiment integer not null check (experiment in (1, 2)),
  model text not null,
  clip text not null,
  condition text not null,
  variant text,
  take integer not null,
  naturalness integer not null check (naturalness between 1 and 5),
  human_or_ai text check (human_or_ai in ('Human', 'AI')),
  question_answered text,
  intended_question text,
  interpretation text check (interpretation in ('A', 'B')),
  intended_interpretation text check (intended_interpretation in ('A', 'B')),
  listened_ms integer not null,
  created_at timestamptz not null default now(),
  -- One response per (participant, session, round). Was a UNIQUE INDEX with a plain-index
  -- fallback in SQLite; now a real constraint (the migration script drops pre-existing dupes).
  constraint responses_round_unique unique (participant, session, round)
);

-- ---------------------------------------------------------------- accounts

create table public.users (
  id bigint generated by default as identity primary key,
  google_sub text not null unique,
  email text,
  name text,
  created_at timestamptz not null default now()
);

create table public.sessions (
  -- SHA-256 of the cookie value; the token itself is never stored.
  token_hash text primary key,
  user_id bigint not null references public.users (id) on delete cascade,
  created_at timestamptz not null default now(),
  -- Epoch milliseconds (exceeds int4).
  expires_at bigint not null
);
create index sessions_user on public.sessions (user_id);

-- ---------------------------------------------------------------- recordings

create table public.recordings (
  id bigint generated by default as identity primary key,
  user_id bigint not null references public.users (id) on delete cascade,
  experiment integer not null check (experiment in (1, 2)),
  prompt_id text not null,
  created_at timestamptz not null default now(),
  mime text not null,
  -- Object key in the private Storage bucket: <userId>/<uuid>.<ext>. Server-generated.
  path text not null,
  size integer not null
);
create index recordings_user on public.recordings (user_id, id);

-- ---------------------------------------------------------------- aggregates
-- PostgREST cannot express GROUP BY, so the three leaderboard queries are views returning the
-- exact shapes of getExp1Counts / getExp2Counts / getExp2InterpBySentence (camelCase columns are
-- quoted so they survive). security_invoker: the view runs with the caller's rights, so it can
-- never leak past RLS; only the service role can read it.

create view public.exp1_counts with (security_invoker = true) as
select provider,
  count(*)::int as "trials",
  count(question_answered)::int as "focusN",
  (count(*) filter (where question_answered = intended_question))::int as "focusCorrect",
  count(naturalness)::int as "natN",
  coalesce(sum(naturalness), 0)::int as "natSum",
  count(human_or_ai)::int as "humanAiN",
  (count(*) filter (where human_or_ai = 'Human'))::int as "judgedHuman"
from public.exp1_trials
where not is_attention_check
group by provider;

create view public.exp2_counts with (security_invoker = true) as
select provider,
  count(*)::int as "trials",
  count(interpretation)::int as "interpN",
  (count(*) filter (where interpretation = intended_interpretation))::int as "interpCorrect",
  count(naturalness)::int as "natN",
  coalesce(sum(naturalness), 0)::int as "natSum"
from public.exp2_trials
where not is_attention_check
group by provider;

create view public.exp2_interp_by_sentence with (security_invoker = true) as
select provider, condition,
  count(interpretation)::int as "n",
  (count(*) filter (where interpretation = intended_interpretation))::int as "correct"
from public.exp2_trials
where not is_attention_check
group by provider, condition;

-- ---------------------------------------------------------------- atomic seeding
-- One call = one transaction: either every row lands or none does, and a table that already
-- has rows is left untouched (returns 0) unless p_replace, which empties it first. The table
-- lock makes two concurrent seeders safe. Not security definer: runs as the caller.

create function public.seed_exp1_trials(p_rows jsonb, p_replace boolean default false)
returns integer language plpgsql set search_path = '' as $$
declare n integer;
begin
  lock table public.exp1_trials in exclusive mode;
  if p_replace then
    delete from public.exp1_trials where true;  -- PostgREST preloads safeupdate
  elsif exists (select 1 from public.exp1_trials) then
    return 0;
  end if;
  insert into public.exp1_trials (participant, trial_number, is_attention_check, provider, condition,
    take, audio_file, intended_question, naturalness, human_or_ai, question_answered)
  select participant, trial_number, is_attention_check, provider, condition,
    take, audio_file, intended_question, naturalness, human_or_ai, question_answered
  from jsonb_to_recordset(p_rows) as r(participant text, trial_number integer, is_attention_check boolean,
    provider text, condition text, take integer, audio_file text, intended_question text,
    naturalness integer, human_or_ai text, question_answered text);
  get diagnostics n = row_count;
  return n;
end $$;

create function public.seed_exp2_trials(p_rows jsonb, p_replace boolean default false)
returns integer language plpgsql set search_path = '' as $$
declare n integer;
begin
  lock table public.exp2_trials in exclusive mode;
  if p_replace then
    delete from public.exp2_trials where true;  -- PostgREST preloads safeupdate
  elsif exists (select 1 from public.exp2_trials) then
    return 0;
  end if;
  insert into public.exp2_trials (participant, trial_number, is_attention_check, provider, condition,
    variant, take, audio_file, intended_interpretation, interpretation, naturalness)
  select participant, trial_number, is_attention_check, provider, condition,
    variant, take, audio_file, intended_interpretation, interpretation, naturalness
  from jsonb_to_recordset(p_rows) as r(participant text, trial_number integer, is_attention_check boolean,
    provider text, condition text, variant text, take integer, audio_file text,
    intended_interpretation text, interpretation text, naturalness integer);
  get diagnostics n = row_count;
  return n;
end $$;

-- After copying rows with explicit ids (scripts/migrate-sqlite-to-supabase.ts), move each
-- identity sequence past the largest id so new inserts don't collide.
create function public.reset_identity_sequences()
returns void language plpgsql set search_path = '' as $$
declare t text;
begin
  foreach t in array array['exp1_trials', 'exp2_trials', 'responses', 'users', 'recordings'] loop
    execute format(
      'select setval(pg_get_serial_sequence(%L, ''id''), coalesce((select max(id) from public.%I), 0) + 1, false)',
      'public.' || t, t);
  end loop;
end $$;

-- ---------------------------------------------------------------- lock down

alter table public.exp1_trials enable row level security;
alter table public.exp2_trials enable row level security;
alter table public.responses enable row level security;
alter table public.users enable row level security;
alter table public.sessions enable row level security;
alter table public.recordings enable row level security;

revoke all on public.exp1_trials, public.exp2_trials, public.responses, public.users, public.sessions,
  public.recordings, public.exp1_counts, public.exp2_counts, public.exp2_interp_by_sentence
  from anon, authenticated;
revoke all on function public.seed_exp1_trials(jsonb, boolean), public.seed_exp2_trials(jsonb, boolean),
  public.reset_identity_sequences() from public, anon, authenticated;
grant execute on function public.seed_exp1_trials(jsonb, boolean), public.seed_exp2_trials(jsonb, boolean),
  public.reset_identity_sequences() to service_role;

-- ---------------------------------------------------------------- storage
-- Private bucket for Record-tab uploads. No storage.objects policies: only the service role
-- reads or writes, and the audio route streams objects to their owner after its own check.
-- The app reads the name from SUPABASE_RECORDINGS_BUCKET (default 'recordings'); create a
-- bucket by hand if you change it.
insert into storage.buckets (id, name, public, file_size_limit)
values ('recordings', 'recordings', false, 5242880)
on conflict (id) do nothing;
